/* Skin "claude" (Claude): the tweakcn preset "claude" (Apache-2.0, see NOTICE.md), written by packages/skins/tools/tweakcn-skins.ts.
   On when data-skin="claude" is on <html> (the page) or on any element (a tile of /skins/). Values as tweakcn exports them;
   the spacing scale stays the kit's 0.25rem. Fonts: system. */
[data-skin="claude"] {
  --background: hsl(48 33% 97%);
  --foreground: hsl(48 20% 20%);
  --card: hsl(48 33% 97%);
  --card-foreground: hsl(60 3% 8%);
  --popover: hsl(0 0% 100%);
  --popover-foreground: hsl(51 19% 13%);
  --primary: hsl(15.3 55.2% 47.3%);
  --primary-foreground: hsl(0 0% 100%);
  --secondary: hsl(46 23% 89%);
  --secondary-foreground: hsl(51 8% 30%);
  --muted: hsl(44 29% 90%);
  --muted-foreground: hsl(50 3% 40%);
  --accent: hsl(46 23% 89%);
  --accent-foreground: hsl(51 19% 13%);
  --destructive: hsl(60 3% 8%);
  --destructive-foreground: hsl(0 0% 100%);
  --border: hsl(50 7% 84%);
  --input: hsl(51 8% 68%);
  --ring: hsl(15.1 55.6% 52.4%);
  --chart-1: hsl(18 57% 44%);
  --chart-2: hsl(251.5 84.6% 74.5%);
  --chart-3: hsl(46 28% 82%);
  --chart-4: hsl(256.6 49.2% 88.4%);
  --chart-5: hsl(18 60% 44%);
  --sidebar: hsl(51 26% 95%);
  --sidebar-foreground: hsl(60 3% 23%);
  --sidebar-primary: hsl(15.1 55.6% 52.4%);
  --sidebar-primary-foreground: hsl(0 0% 98%);
  --sidebar-accent: hsl(46 23% 89%);
  --sidebar-accent-foreground: hsl(0 0% 20%);
  --sidebar-border: hsl(0 0% 92%);
  --sidebar-ring: hsl(0 0% 71%);
  --font-sans: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, 'Noto Sans', sans-serif, 'Apple Color Emoji', 'Segoe UI Emoji', 'Segoe UI Symbol', 'Noto Color Emoji';
  --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
  --radius: 0.5rem;
  --shadow-2xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-sm: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 1px 2px -1px hsl(0 0% 0% / 0.10);
  --shadow: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 1px 2px -1px hsl(0 0% 0% / 0.10);
  --shadow-md: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 2px 4px -1px hsl(0 0% 0% / 0.10);
  --shadow-lg: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 4px 6px -1px hsl(0 0% 0% / 0.10);
  --shadow-xl: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 8px 10px -1px hsl(0 0% 0% / 0.10);
  --shadow-2xl: 0 1px 3px 0px hsl(0 0% 0% / 0.25);
  --destructive-hover: hsl(60 3% 2%);
}

:is(.dark, [data-theme="dark"]) [data-skin="claude"],
[data-skin="claude"]:is(.dark, [data-theme="dark"]) {
  --background: hsl(60 2.7% 14.5%);
  --foreground: hsl(46 10% 74%);
  --card: hsl(60 2.7% 14.5%);
  --card-foreground: hsl(48 33% 97%);
  --popover: hsl(60 2.1% 18.4%);
  --popover-foreground: hsl(60 5% 89%);
  --primary: hsl(14.8 52.1% 47.5%);
  --primary-foreground: hsl(0 0% 100%);
  --secondary: hsl(48 33% 97%);
  --secondary-foreground: hsl(60 2.1% 18.4%);
  --muted: hsl(60 4% 10%);
  --muted-foreground: hsl(51 9% 69%);
  --accent: hsl(48 11% 9%);
  --accent-foreground: hsl(51 26% 95%);
  --destructive: hsl(358.3 71.8% 52.7%);
  --destructive-foreground: hsl(0 0% 100%);
  --border: hsl(60 5% 23%);
  --input: hsl(52 5% 31%);
  --ring: hsl(14.8 63.1% 59.6%);
  --chart-1: hsl(18 57% 44%);
  --chart-2: hsl(251.5 84.6% 74.5%);
  --chart-3: hsl(48 11% 9%);
  --chart-4: hsl(248 25% 23%);
  --chart-5: hsl(18 60% 44%);
  --sidebar: hsl(30 3% 12%);
  --sidebar-foreground: hsl(46 10% 74%);
  --sidebar-primary: hsl(0 0% 20%);
  --sidebar-primary-foreground: hsl(0 0% 98%);
  --sidebar-accent: hsl(60 3% 6%);
  --sidebar-accent-foreground: hsl(46 10% 74%);
  --sidebar-border: hsl(0 0% 92%);
  --sidebar-ring: hsl(0 0% 71%);
  --shadow-2xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-sm: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 1px 2px -1px hsl(0 0% 0% / 0.10);
  --shadow: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 1px 2px -1px hsl(0 0% 0% / 0.10);
  --shadow-md: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 2px 4px -1px hsl(0 0% 0% / 0.10);
  --shadow-lg: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 4px 6px -1px hsl(0 0% 0% / 0.10);
  --shadow-xl: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 8px 10px -1px hsl(0 0% 0% / 0.10);
  --shadow-2xl: 0 1px 3px 0px hsl(0 0% 0% / 0.25);
  --destructive-hover: hsl(358.3 71.8% 46.7%);
}

[data-skin="claude"] .shadow-xs { --tw-shadow: var(--shadow-xs); }
[data-skin="claude"] .shadow-sm { --tw-shadow: var(--shadow-sm); }
[data-skin="claude"] .shadow { --tw-shadow: var(--shadow); }
[data-skin="claude"] .shadow-md { --tw-shadow: var(--shadow-md); }
[data-skin="claude"] .shadow-lg { --tw-shadow: var(--shadow-lg); }
[data-skin="claude"] .shadow-xl { --tw-shadow: var(--shadow-xl); }
